    // TC-003 - Verify payment made during order creation is recorded and reflected in today's earnings
    @Test
    public void verifyPaymentDuringOrderCreationReflectsInTodaysEarnings() {
        // Precondition: Create a shop
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "1234567890",
              "latitude": 23.8103,
              "longitude": 90.4125,
              "ownerName": "Owner",
              "email": "owner_%d@example.com",
              "address": "Dhaka",
              "areaId": 1,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis());
        Long shopId = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/1/shops").then().statusCode(anyOf(is(200), is(201))).extract().path("id");
        // Precondition: Create an item
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "শার্ট",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(System.currentTimeMillis());
        Long itemId = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().path("data.id");
        // Precondition: Get today's earnings before order creation
        BigDecimal todaysEarningsBefore = given().when().get("/api/dashboard/summary").then().statusCode(200).extract().path("data.todaysEarnings");
        // Create order with payment
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "Customer",
              "customerPhone": "9876543210",
              "customerGender": "MALE",
              "paidAmount": 500,
              "deliveryDate": "2023-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "specialInstruction": "None",
                      "makingCharge": 500,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, itemId);
        given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201)));
        // Verify today's earnings increased by paid amount
        given().when().get("/api/dashboard/summary").then().statusCode(200).body("data.todaysEarnings", equalTo(todaysEarningsBefore.add(new BigDecimal(500)).floatValue()));
    }

