    // TC-021 - Verify that updating an order item status to CANCELLED recalculates the order's due amount and reflects it in the dashboard totals
    @Test
    public void verifyOrderItemCancellationRecalculatesDueAmount() {
        String updateStatusBody = """
            {
              "newStatus": "CANCELLED"
            }
            """;
        // Update order item status to CANCELLED
        given().contentType(ContentType.JSON).body(updateStatusBody).when().put("/api/orders/items/{orderItemId}/status", orderItemId).then().statusCode(200);
        // Verify order due amount is recalculated
        given().when().get("/api/orders/{orderId}", orderId).then().statusCode(200).body("data.dueAmount", equalTo(1000.0F));
        // Verify dashboard total due is updated (simplified check)
        given().when().get("/api/dashboard/summary").then().statusCode(200).body("data.totalDue", notNullValue());
    }

    // TC-022 - Verify that updating an order item status to CANCELLED does not allow negative due amounts
    @Test
    public void verifyOrderItemCancellationDoesNotAllowNegativeDueAmount() {
        // Create a new order with paidAmount = totalAmount (dueAmount = 0)
        String itemBody = """
            {
              "nameEn": "Test Item 2",
              "nameBn": "টেস্ট আইটেম ২",
              "status": "ACTIVE",
              "parameters": []
            }
            """;
        Long itemId = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().path("data.id");
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "Test Customer 2",
              "customerPhone": "5550000002",
              "customerGender": "MALE",
              "paidAmount": 5000,
              "deliveryDate": "2023-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "specialInstruction": "None",
                      "makingCharge": 5000,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, itemId);
        Long newOrderId = given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().path("data.id");
        Long newOrderItemId = given().when().get("/api/orders/{orderId}", newOrderId).then().statusCode(200).extract().path("data.items[0].id");
        String updateStatusBody = """
            {
              "newStatus": "CANCELLED"
            }
            """;
        // Update order item status to CANCELLED
        given().contentType(ContentType.JSON).body(updateStatusBody).when().put("/api/orders/items/{orderItemId}/status", newOrderItemId).then().statusCode(200);
        // Verify order due amount remains 0
        given().when().get("/api/orders/{orderId}", newOrderId).then().statusCode(200).body("data.dueAmount", equalTo(0.0F));
    }

    // TC-023 - Verify that dashboard financial totals are not affected by rapid successive order creations (rate limiting)
    // Disabled as rate limiting is typically tested via load testing tools
    @Test(enabled = false)
    public void verifyDashboardTotalsNotAffectedByRapidOrderCreations() {
        // This test is conceptual as REST Assured isn't ideal for rate limiting tests
        // In practice, use a load testing tool like JMeter for this scenario
        // Create 10 orders rapidly
        for (int i = 1; i <= 10; i++) {
            String orderBody = """
                {
                  "shopId": %d,
                  "customerName": "Test User %d",
                  "customerPhone": "55500000%02d",
                  "customerGender": "MALE",
                  "paidAmount": 1000,
                  "deliveryDate": "2023-12-31",
                  "items": [
                    {
                      "itemId": %d,
                      "measurementGroups": [
                        {
                          "specialInstruction": "None",
                          "makingCharge": 1000,
                          "measurements": []
                        }
                      ]
                    }
                  ]
                }
                """.formatted(shopId, i, i, itemId);
            given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(// 429 for Too Many Requests
            anyOf(is(200), is(201), is(429)));
        }
        // Check dashboard summary (simplified)
        given().when().get("/api/dashboard/summary").then().statusCode(200).body("data.earningToday", anyOf(equalTo(10000.0F), lessThanOrEqualTo(10000.0F)));
    }

